<?php
declare(strict_types=1);
function document_markup(array $d,array $items,bool $pdf=false): string { $s=json_decode($d['snapshot']??'null',true)??['business'=>profile()+['name'=>business()['name']],'customer'=>['name'=>$d['customer_name'],'address'=>$d['customer_address'],'email'=>$d['customer_email'],'gstin'=>$d['customer_gstin']]];$b=$s['business'];$c=$s['customer'];ob_start(); ?>
<div class="invoice-header"><div><div class="brand-mark">y<span>b</span>t<span class="brand-dot">.</span></div><strong><?= e($b['name']) ?></strong></div><div><h2><?= $d['type']==='invoice'?'INVOICE':'QUOTATION' ?></h2><p><?= e($d['number']) ?> · <?= badge(document_status($d)) ?></p></div></div><div class="invoice-addresses"><div><small>From</small><strong><?= e($b['name']) ?></strong><br><?= e($b['address']??'') ?><br><?= e($b['email']??'') ?><?= empty($b['gstin'])?'':'<br>GSTIN: '.e($b['gstin']) ?></div><div><small>Bill to</small><strong><?= e($c['name']) ?></strong><br><?= e($c['address']??'') ?><br><?= e($c['email']??'') ?><?= empty($c['gstin'])?'':'<br>GSTIN: '.e($c['gstin']) ?></div><div><small>Document date</small><?= date_label($d['issue_date']) ?><br><br><small><?= $d['type']==='invoice'?'Due date':'Valid until' ?></small><?= date_label($d['due_date']) ?></div></div><div class="table-scroll"><table><thead><tr><th>DESCRIPTION</th><th>QTY</th><th>RATE</th><th>DISCOUNT</th><th>TAX</th><th>AMOUNT</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><strong><?= e($i['description']) ?></strong></td><td><?= e(rtrim(rtrim($i['quantity'],'0'),'.')) ?></td><td><?= money($i['rate']) ?></td><td><?= e($i['discount_rate']) ?>%</td><td><?= e($i['tax_rate']) ?>%</td><td><strong><?= money($i['total']) ?></strong></td></tr><?php endforeach; ?></tbody></table></div><div class="invoice-totals"><div><span>Subtotal</span><span><?= money($d['subtotal']) ?></span></div><div><span>Discount</span><span>− <?= money($d['discount_total']) ?></span></div><div><span>Tax</span><span><?= money($d['tax_total']) ?></span></div><div class="total"><strong>Grand total</strong><strong><?= money($d['total']) ?></strong></div><?php if($d['type']==='invoice'): ?><div><span>Amount paid</span><span><?= money($d['paid']) ?></span></div><div><strong>Outstanding balance</strong><strong><?= money(max(0,(float)$d['total']-(float)$d['paid'])) ?></strong></div><?php endif; ?></div><div class="invoice-notes"><strong>Notes & terms</strong><br><?= e($d['notes']) ?><?php if(!empty($b['payment_instructions'])): ?><br><br><strong>Payment instructions</strong><br><?= e($b['payment_instructions']) ?><?php endif; ?></div>
<?php return ob_get_clean(); }
